/*The BankCrad is a card that can deposit or withdraw money.*/
class BankCard {
  /*The unique identifier of the bank card*/
  CardID: number;
  /*The status of the bank card*/
  CardStatus: CardStatus;
  /*The catalog of the bank card*/
  Catalog: CardCatalog;
  /*The password of the bank card*/
  Password: number;
  /*The balance of the bank card*/
  Balance: number;
  /*The user who owns the bank card*/
  BelongedUser: User;
}
/*Bank user information.*/
class User {
  /*The id of the user*/
  UserID: number;
  /*The name of the user*/
  Name: string;
  /*The address of the user*/
  Address: string;
  /*The bank card owned by the user*/
  OwnedCard: BankCard;
}
enum CardStatus {
  NORMAL = "NORMAL",
  SUSPEND = "SUSPEND",
  CANNEL = "CANNEL",
}
enum CardCatalog {
  CREDIT = "CREDIT",
  DESPOSIT = "DESPOSIT",
}
const map = new Map();
map.set(BankCard, []);
map.set(User, []);
const getRepository = <T,>(clazz: new (...args: any[]) => T) => {
  return map.get(clazz) as T[];
};
export { CardStatus, CardCatalog, BankCard, User, getRepository };

typescript.originalService:
class AutomatedTellerMachineSystem_AutoGenerated {
  /*SystemVariable Start*/
  PasswordValidated: boolean;
  WithdrawedNumber: number;
  InputCard: BankCard;
  CardIDValidated: boolean;
  IsDeposit: boolean;
  IsWithdraw: boolean;
  DepositedNumber: number;
  /*SystemVariable End*/

  /*if the card password and id is validated,
   *and the input card exists and the input quantity greater or equal to 100, then the input card balance will plus the quantity
   *and the deposited number is equal to the deposited number.*/
  depositFunds(quantity: number): boolean {
    /*Definition Start*/
    let validCard: boolean = l()
      .if({
        logic: () =>
          l({
            logic: () => this.InputCard !== false,
            description: "InputCard<>invalid",
          })
            .and({
              logic: () => this.CardIDValidated,
              description: "CardIDValidated",
            })
            .and({
              logic: () => this.PasswordValidated,
              description: "PasswordValidated",
            }),
        description: "InputCard<>invalidandCardIDValidatedandPasswordValidated",
        then: l({
          logic: () => true,
          description: "true",
        }),
        else: l({
          logic: () => false,
          description: "false",
        }),
      })
      .build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => validCard,
        description: "validCard",
      })
        .and({
          logic: () => StandardOPs.oclIsTypeOf(this.InputCard, BankCard),
          description: "InputCard.oclIsTypeOf(BankCard)",
        })
        .and({
          logic: () => this.InputCard.CardStatus === CardStatus.NORMAL,
          description: "InputCard.CardStatus=CardStatus::NORMAL",
        })
        .and({
          logic: () => quantity >= 100,
          description: "quantity>=100.0",
        })
        .and({
          logic: () => getRepository(BankCard).includes(this.InputCard),
          description: "BankCard.allInstance()->includes(InputCard)",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let updatedCard: BankCard;
    return l({
      execute: () => (updatedCard = new BankCard()),
      description: "updatedCard.oclIsNew()",
    })
      .and({
        execute: () => (updatedCard.CardID = this.InputCard.CardID),
        description: "updatedCard.CardID=InputCard.CardID",
      })
      .and({
        execute: () => (updatedCard.CardStatus = this.InputCard.CardStatus),
        description: "updatedCard.CardStatus=InputCard.CardStatus",
      })
      .and({
        execute: () => (updatedCard.Catalog = this.InputCard.Catalog),
        description: "updatedCard.Catalog=InputCard.Catalog",
      })
      .and({
        execute: () => (updatedCard.Password = this.InputCard.Password),
        description: "updatedCard.Password=InputCard.Password",
      })
      .and({
        execute: () =>
          (updatedCard.Balance = this.InputCard.Balance + quantity),
        description: "updatedCard.Balance=InputCard.Balance+quantity",
      })
      .and({
        execute: () => getRepository(BankCard).push(updatedCard),
        description: "BankCard.allInstance()->includes(updatedCard)",
      })
      .and({
        execute: () => (this.DepositedNumber = quantity),
        description: "DepositedNumber=quantity",
      })
      .and({
        execute: () => true,
        description: "result=true",
      })
      .build().value;
    /*Postcondition End*/
  }
}
export { AutomatedTellerMachineSystem_AutoGenerated };

